(function(){let next=1,worker,workerURL;const pending=new Map();function fallback(image,options){return new Promise((resolve,reject)=>setTimeout(()=>{try{resolve(FragmentVectorize.trace(image,options))}catch(e){reject(e)}},0))}function revoke(){if(workerURL){URL.revokeObjectURL(workerURL);workerURL=null}}function createWorker(){if(worker)return worker;try{workerURL=URL.createObjectURL(new Blob([FragmentVectorize.workerSource()],{type:'application/javascript'}));worker=new Worker(workerURL);worker.onmessage=e=>{revoke();const job=pending.get(e.data.id);if(!job)return;pending.delete(e.data.id);e.data.error?job.reject(Error(e.data.error)):job.resolve(e.data.result)};worker.onerror=()=>{revoke();worker.terminate();worker=null;for(const job of pending.values())fallback(job.image,job.options).then(job.resolve,job.reject);pending.clear()};return worker}catch{revoke();worker=null;return null}}async function trace(image,{colors=0,detail=1024}={}){const ratio=Math.min(1,detail/Math.max(image.width,image.height)),canvas=off(Math.max(1,Math.round(image.width*ratio)),Math.max(1,Math.round(image.height*ratio))),context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0,canvas.width,canvas.height);const pixels=context.getImageData(0,0,canvas.width,canvas.height),options={colors,outputWidth:image.width,outputHeight:image.height};const active=typeof Worker!=='undefined'?createWorker():null;if(!active)return fallback(pixels,options);const id=next++;return new Promise((resolve,reject)=>{pending.set(id,{resolve,reject,image:pixels,options});try{active.postMessage({id,image:pixels,options})}catch{pending.delete(id);fallback(pixels,options).then(resolve,reject)}})}window.FragmentVector={trace};})();
